<?php use App\Core\Format;$slug=$tenant['slug'];$today=date('Y-m-d');?>
<section class="card gantt-card"><div class="gantt-head"><div><h2>Gráfico Gantt — Cronograma dinâmico</h2><p>Os blocos mantêm os dias planejados; as datas operacionais são recalculadas pelo encerramento formal da fase anterior.</p></div><div class="gantt-head-chips"><span class="gantt-chip"><?=count($fasesVisiveis)?> fase(s)</span><span class="gantt-chip">Início: <?=Format::h(Format::date($dataInicioProcesso))?></span><span class="gantt-chip">Hoje: D<?=$diaAtualProjeto?> · <?=Format::h(Format::date($today))?></span></div></div>
<div class="gantt-body"><div class="gantt-scale"><div></div><div class="gantt-days"><?php for($i=0;$i<10;$i++):$day=1+(int)round(($maxDiaCronograma-1)*$i/9);?><span>D<?=$day?></span><?php endfor;?></div></div>
<?php foreach($fasesVisiveis as $f):$d=$cronogramaPorFase[(int)$f['id']]??null;$start=!empty($d['inicio'])?max(1,(new DateTimeImmutable($dataInicioProcesso))->diff(new DateTimeImmutable($d['inicio']))->days+1):(int)$f['dia_inicio'];$end=!empty($d['fim'])?max($start,(new DateTimeImmutable($dataInicioProcesso))->diff(new DateTimeImmutable($d['fim']))->days+1):(int)$f['dia_fim'];$left=max(0,min(100,(($start-1)/max(1,$maxDiaCronograma-1))*100));$rawWidth=max(1.5,(($end-$start+1)/$maxDiaCronograma)*100);$width=min($rawWidth,max(0.5,100-$left));$status=$d['status']??'blocked';$completed=in_array($status,['completed-on-time','completed-late'],true);$completePos=min(99.6,$left+$width);?>
<div class="gantt-row"><div class="gantt-label"><b>Fase <?=Format::h($f['ordem'])?> — <?=Format::h($f['aba'])?></b><?=Format::h($f['titulo'])?><br><span>Planejado: Dia <?=Format::h($f['dia_inicio'])?> ao <?=Format::h($f['dia_fim'])?></span><span class="gantt-operational-date">Operacional: <?=Format::h(Format::date($d['inicio']??null))?> a <?=Format::h(Format::date($d['fim']??null))?></span><span class="gantt-operational-status <?=Format::h($status)?>"><?=Format::h($d['rotulo']??'Aguardando')?></span></div><div class="gantt-line"><?php if($completed):?><i class="gantt-completed <?=$status==='completed-late'?'late':'done'?>" style="left:<?=number_format($completePos,4,'.','')?>%"></i><?php elseif($diaAtualProjeto<=$maxDiaCronograma):?><i class="gantt-today" style="left:<?=number_format($percentualHojeGantt,4,'.','')?>%"></i><?php endif;?><div class="gantt-bar deadline-<?=Format::h($status)?>" style="left:<?=number_format($left,4,'.','')?>%;width:<?=number_format($width,4,'.','')?>%"><span class="gantt-tag"><?=max(1,$end-$start+1)?> dia(s)</span></div></div></div>
<?php endforeach;?></div><div class="gantt-legend"><span><i class="green"></i>Encerrada no prazo</span><span><i class="orange"></i>Em andamento / atenção</span><span><i class="red"></i>Atraso</span><span><i class="gray"></i>Aguardando fase anterior</span></div></section>
